window.products.push({"id":1080187,"name":"Future Way 2.5 Pound Black Lava Rocks for Plant, Succulent, Landscaping, Top-Dressing, Pure Volcanic Rocks, 1/5 Inch","category":"homeandappliances","retail price":9.99,"sale price":null,"image":"https://m.media-amazon.com/images/I/81KGDpWmHVL._AC_SL1500_.jpg","description":"【Ideal Size】 These volcanic rocks measure about 1/5 inch and come in various shapes, adding a unique aesthetic to your potted plants 【Widely Application】 Perfect for acting as soil additives or top dressing for potted plants, such as vase filler, terrarium, succulent, cactus bonsai, houseplant and more 【All Nature】 Naturally formed after eruptions, the volcanic rock is pure and rich in minerals conducive to plant growth, and safe for the natural growth of your plants. Buy with confidence 【Benefits For Plants】 Besides adjusting the PH of soil, porous lava rocks allow for better drainage, improve soil aeration and promote strong root growth 【Low Maintenance】 Lava rock doesn't decompose and requires almost no maintenance, so you don't need to worry about replenishing it","images":["https://m.media-amazon.com/images/I/81KGDpWmHVL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Future Way","source_asin":"B0BRG17HRX","category_path":"Home & Kitchen"},"sku":"BM-1080187","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B0BRG17HRX","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B0BRG17HRX","price_pending":true,"merchant_ready":false});
